// Upstream CSS, line for line, with component-prefixed parts (data-slot),
// keyframes (clatter-shake-*) and colors (--clatter-shake-*). Mirrored as a
// whole in a right-to-left context. React 19 hoists this <style> into <head>
// once, however many instances render.
const css = `
[data-slot="clatter-shake-panel"] {
  position: relative;
  animation: clatter-shake-translate-x 0.84s ease-in-out 0s both;
}
[data-slot="clatter-shake-panel"]:dir(rtl) {
  scale: -1 1;
}
@keyframes clatter-shake-translate-x {
  from {
    transform: translateX(32%);
  }
  40% {
    transform: translateX(-16%);
  }
  70% {
    transform: translateX(8%);
  }
  to {
    transform: translateX(0%);
  }
}

[data-slot="clatter-shake-inner"] {
  position: relative;
  animation: clatter-shake-translate-y 0.84s ease-in-out 0s both;
}
[data-slot="clatter-shake-inner"]::after {
  content: "";
  position: absolute;
  top: 0;
  left: 50%;
  transform: translate(-50%, -95%);
  width: 6%;
  height: 200%;
  background-color: var(--clatter-shake-string, #888);
  border-radius: 999px;
}
@keyframes clatter-shake-translate-y {
  from {
    transform: translateY(-150%);
  }
  40% {
    transform: translateY(20%);
  }
  60% {
    transform: translateY(0);
  }
  80% {
    transform: translateY(10%);
  }
  to {
    transform: translateY(0);
  }
}

[data-slot="clatter-shake-tag"] {
  position: relative;
  width: 90px;
  aspect-ratio: 20 / 26;
  border-radius: 12px;
  background-color: var(--clatter-shake-tag, #bbb);
  transform-origin: 50% 10%;
  animation: clatter-shake-shake 0.84s ease-in-out 0s both;
}
[data-slot="clatter-shake-tag"]::after {
  content: "";
  display: block;
  position: absolute;
  top: 8%;
  left: 50%;
  transform: translateX(-50%);
  width: 15%;
  aspect-ratio: 1;
  border-radius: 50%;
  background-color: var(--clatter-shake-hole, #eee);
}
@keyframes clatter-shake-shake {
  from {
    transform: rotate(50deg);
  }
  40% {
    transform: rotate(-16deg);
  }
  70% {
    transform: rotate(8deg);
  }
  to {
    transform: rotate(0deg);
  }
}

/* Optional content on the tag, below the hole. */
[data-slot="clatter-shake-content"] {
  position: absolute;
  inset: 26% 8% 8%;
  display: grid;
  place-items: center;
  text-align: center;
}
[data-slot="clatter-shake-panel"]:dir(rtl) [data-slot="clatter-shake-content"] {
  scale: -1 1;
}

/* Reduced motion: no motion; the tag hangs at rest. */
@media (prefers-reduced-motion: reduce) {
  [data-slot="clatter-shake-panel"],
  [data-slot="clatter-shake-inner"],
  [data-slot="clatter-shake-tag"] {
    animation: none;
  }
}
`;

/**
 * A tag drops in on its string and clatters from side to side until it
 * hangs still, once on mount. Children render on the tag. Remount it (change
 * its `key`) to play it again.
 */
function ClatterShake({
  className,
  children,
  ...props
}: React.ComponentProps<"div">) {
  const labelled =
    props["aria-label"] !== undefined || props["aria-labelledby"] !== undefined;
  const decorative = !labelled && children == null;
  return (
    <div
      data-slot="clatter-shake"
      role={labelled && children == null ? "img" : undefined}
      aria-hidden={decorative ? true : undefined}
      className={cn(
        "relative grid aspect-square w-full max-w-80 place-content-center overflow-hidden bg-[var(--clatter-shake-surface,#fff)]",
        className,
      )}
      {...props}
    >
      <style href="designfrom-clatter-shake" precedence="default">
        {css}
      </style>
      <div data-slot="clatter-shake-panel">
        <div data-slot="clatter-shake-inner">
          <div data-slot="clatter-shake-tag">
            {children == null ? null : (
              <div data-slot="clatter-shake-content">{children}</div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

export { ClatterShake };
